code='''def transform(grid):
    n = len(grid)
    k = next(size for size in range(1, n + 1) if size * size + size - 1 == n)
    step = k + 1
    out = [row[:] for row in grid]

    def tile_at(i, j):
        r0, c0 = i * step, j * step
        return [grid[r0 + r][c0:c0 + k] for r in range(k)]

    def has_shape(tile):
        return any(value == 2 for row in tile for value in row)

    template = next(tile_at(i, j) for i in range(k) for j in range(k)
                    if not any(3 in row for row in tile_at(i, j)) and has_shape(tile_at(i, j)))

    for r in range(n):
        for c in range(n):
            if out[r][c] == 3:
                out[r][c] = 0

    for i in range(k):
        for j in range(k):
            r0, c0 = i * step, j * step
            tile = tile_at(i, j)
            masked = any(value == 3 for row in tile for value in row)
            if masked:
                source = tile_at(j, i)
                if template[i][j] == 2 and (has_shape(source) or i == j):
                    source = source if has_shape(source) else template
                    for r in range(k):
                        for c in range(k):
                            out[r0 + r][c0 + c] = source[r][c]
            if not masked or (template[i][j] == 2 and (has_shape(tile_at(j, i)) or i == j)):
                if out[r0 + i][c0 + j] == 2:
                    out[r0 + i][c0 + j] = 8
    return out
'''
